#!/usr/bin/env python3
from __future__ import annotations
# MAX_WALLCLOCK_SECONDS=600 VAL_LOSS_EVERY=0 final_int8_zlib_roundtrip_exact
import base64
import zlib
_CODE_B64 = ""
code = zlib.decompress(base64.b64decode(_CODE_B64)).decode("utf-8")
code = code.replace('    code = Path(__file__).read_text(encoding="utf-8")\n', '    code = __patched_source__\n', 1)
globals()["__patched_source__"] = code
exec(compile(code, __file__, "exec"), globals(), globals())
